const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,csrf,botId='concierge',property='sweetfun',dataset='live',tab='chat',conversation=null,pending=false,histories=[],settingsTab='bots',selectedTool='',docRows=[],toolResult=null;
let hostState=null,hostPairing=null,hostTimer=null;
const bot=()=>state.bots.find(x=>x.id===botId)||state.bots.find(x=>x.active),role=()=>state.roles[bot().role];
const fmt=x=>x===null||x===undefined?'未知':typeof x==='number'?x.toLocaleString('zh-TW',{maximumFractionDigits:2}):typeof x==='boolean'?(x?'是':'否'):typeof x==='object'?JSON.stringify(x):String(x);
const names={id:'識別碼',property:'據點',room:'房間',start:'入住日',end:'退房日',guest:'旅客',total:'訂單總額',channel:'通路',status:'狀態',version:'版本',received:'已收款',balance:'待收',available:'可用',title:'標題',assignee:'負責 Bot',due:'到期日',orderId:'訂單',amount:'金額',method:'方式',receivedAt:'收款日',type:'類型',reason:'原因',reverses:'原收款',name:'來源',url:'證據網址',stayDate:'入住日',nights:'晚數',guests:'人數',price:'報價',taxIncluded:'含稅',cancellation:'取消條件',observedAt:'觀察時間',provenance:'來源狀態',median:'中位數',samples:'樣本數',gap:'資料缺口',updatedAt:'更新時間',category:'分類',content:'內容'};
const toolNames={'overview':'營運概況','tasks.list':'查看任務','tasks.create':'新增任務','tasks.update':'更新任務','delegate':'分派分析','orders.list':'查看訂單','availability':'查詢可用房間','orders.create':'新增隔離訂單','orders.update':'修改隔離訂單','orders.cancel':'取消隔離訂單','finance.summary':'財務核對摘要','payments.record':'登記隔離收款','payments.reverse':'沖銷收款','documents.list':'可讀文件','documents.read':'閱讀文件','documents.create':'新增文件','documents.update':'更新文件','documents.archive':'封存文件','reports.booking':'固定訂房分析','reports.market':'固定市場報告','market.list':'查看市場證據','market.add':'新增市場證據','market.archive':'封存市場證據','calculate':'基本計算','organize':'整理資料'};
async function api(path,opts={}){const r=await fetch('/api/bots/'+path,{...opts,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...opts.headers}});const data=await r.json();if(r.status===401){location.assign('/calendar-access?next=/bots');throw Error('請先登入 Sweetfun OS');}if(!r.ok)throw Error(data.message||'操作失敗');return data;}
const post=(p,b)=>api(p,{method:'POST',body:JSON.stringify(b)});
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4200);}
async function refresh(){state=await api('state');histories=(await api('conversations')).rows;}
function avatar(b,size=''){const r=state.roles[b.role];return `<span class="avatar ${size}" style="--accent:${r.color}">${r.icon}</span>`;}
function render(){const current=bot(),b=tab==='customer'?{...current,name:'民宿客服'}:current,r=role();if(!b)return;botId=b.id;document.documentElement.style.setProperty('--accent',r.color);
 const latest=id=>histories.find(x=>x.botId===id)?.title||({concierge:'有事找我',finance:'收支與對帳',reservations:'訂單與房況',analyst:'訂房分析',market:'市場與競品'}[id]||'開始聊天');
 $('#app').innerHTML=`<div class="shell line-shell"><aside class="sidebar"><div class="list-heading"><h1>聊天</h1><button data-action="more" aria-label="設定">⚙</button></div><div class="contact-list">${state.bots.filter(x=>x.active).map(x=>`<button class="bot-button ${tab!=='customer'&&x.id===b.id?'selected':''}" data-bot="${esc(x.id)}">${avatar(x)}<span><b>${esc(x.name)}</b><small>${esc(latest(x.id))}</small></span></button>`).join('')}<button class="bot-button ${tab==='customer'?'selected':''}" data-action="customer"><span class="avatar">☏</span><span><b>民宿客服</b><small>${hostLabel()}</small></span></button></div><a class="list-home" href="/calendar">返回 Sweetfun OS</a></aside><main class="main"><header class="topbar"><button class="mobile-menu" aria-label="聊天列表" data-action="menu">‹</button>${tab==='customer'?'<span class="avatar">☏</span>':avatar(b)}<div class="chat-heading"><h1>${esc(b.name)}</h1>${tab==='customer'?`<span class="source-chip">${esc(hostLabel())}</span>`:`<button class="source-chip" data-action="source-picker">${property==='sweetfun'?'水芳':'OFFLAND'} · ${dataset==='live'?'目前訂單':dataset==='imported'?'匯入資料':'測試資料'}${dataset!=='sandbox'?' · 唯讀':''}⌄</button>`}</div><button class="more-button" data-action="more" aria-label="更多">•••</button></header><div class="content" id="content">${tab==='customer'?customerHTML():tab==='chat'?chatHTML():`<button class="back-chat" data-tab="chat">‹ 返回聊天</button>`+(tab==='documents'?documentsHTML():tab==='tools'?toolsHTML():tab==='onboarding'?onboardingHTML():settingsHTML())}</div>${tab==='chat'?composer():''}</main></div>`;
 if(tab==='chat'&&conversation)scrollBottom();bindForms();bindOnboarding();bindCustomer();}
function hostLabel(){return ({offline:'主機未連線',login_required:'需要登入 LINE',needs_reauth:'請重新登入 LINE',ready:'主機已連線',error:'主機需要檢查'})[hostState?.host_status]||'主機未連線';}
async function hostRequest(action,body){const res=await fetch('/api/v1/host-agents/owner/'+action,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':'same-origin'},...(body?{body:JSON.stringify(body)}:{})});const out=await res.json();if(!res.ok){const err=Error(({already_paired:'已有配對主機，請先中斷連線。',host_offline:'請先開啟主機程式。',job_in_progress:'正在檢查，請稍候。',login_required:'請先登入 Sweetfun OS。'}[out.error]||customerErrors[out.error])||'連線暫時無法完成，請稍後再試。');err.code=out.error;throw err;}return out;}
async function refreshHost(){if(hostLoading)return;hostLoading=true;const fingerprint=()=>JSON.stringify([hostState?.host_status,hostState?.paired,hostState?.capabilities,customer]);const before=fingerprint();try{hostState=await hostRequest('status');if(hostState.paired)hostPairing=null;await pollCustomer();if(tab==='customer'&&before!==fingerprint())render();}catch(e){toast(e.message);}finally{hostLoading=false;clearTimeout(hostTimer);if(tab==='customer')hostTimer=setTimeout(refreshHost,customer.job?2000:15000);}}

async function pairHost(){hostPairing=await hostRequest('pairing',{property_id:'sweetfun'});render();}
const customerActions={oa_reply:'回覆客人',oa_set_tag:'套用標籤',oa_set_name:'修改名稱'};
const customerErrors={action_outcome_uncertain:'操作結果尚未確認，請先查看 LINE，勿重複送出。',invalid_customer_input:'請核對內容長度：回覆最多 1000 字，標籤與新名稱最多 20 字。',recipient_not_visible:'找不到符合名稱的客人，請核對完整名稱。',recipient_ambiguous:'有同名客人，請先在 LINE 確認正確對話。',recipient_changed:'電腦已切換對話，請重新讀取這位客人的訊息。',conversation_ref_expired:'對話已過期，請重新讀取。',composer_not_empty:'LINE 有尚未送出的草稿，請先在電腦處理。',ui_control_ambiguous:'無法確認 LINE 畫面，請在電腦檢查後再試。',tag_not_available:'請先在 LINE OA 聊天設定建立此標籤，再重新讀取對話操作。',draft_facts_changed:'潤飾結果改變了數字或網址，已保留原文。',provider_not_configured:'Gemini 尚未設定，仍可直接編輯回覆。',provider_error:'暫時無法潤飾，原文已保留。',invalid_model_output:'潤飾結果不完整，原文已保留。',customer_expired:'這份對話已過期，請重新讀取。',read_required:'先讀取客人的最新對話。',capability_unavailable:'主機尚未支援這項操作。',line_login_required:'請在電腦登入 LINE OA。',job_in_progress:'上一項工作還在進行，請稍候。',conversation_ambiguous:'有同名客人，請在電腦先確認正確對話。',conversation_not_found:'找不到這個客人，請核對完整名稱。',conversation_changed:'對話有新變化，請重新讀取再確認。',stale_conversation:'對話已更新，請重新讀取。',read_back_verification_required:'操作結果尚未確認，請查看 LINE，勿重複送出。'};
let customer={list:null,conversation:null,readJobId:null,job:null,query:'',text:'',edit:'',error:'',notice:'',draft:null,sources:[]},hostLoading=false;
function rememberCustomerJob(job){customer.job=job;try{if(job)sessionStorage.setItem('customer-pending-job',JSON.stringify({job_id:job.job_id}));else sessionStorage.removeItem('customer-pending-job');}catch{}}
try{const saved=JSON.parse(sessionStorage.getItem('customer-pending-job')||'null');if(saved&&typeof saved.job_id==='string'){customer.job=saved;tab='customer';}}catch{}
function customerHTML(){
 if(!hostState?.paired)return `<div class="messages"><article class="message assistant">先把你的主機連上來。</article><button class="primary" data-action="host-pair">連接主機</button>${hostPairing?`<section class="pairing-card"><b>在主機程式貼上配對碼</b><code>${esc(hostPairing.pairing_code)}</code><p>5 分鐘內有效</p></section>`:''}</div>`;
 const ready=hostState.host_status==='ready',can=a=>ready&&hostState.capabilities?.[a],busy=!!customer.job;
 const c=customer.conversation;
 return `<section class="customer-workspace"><div class="customer-toolbar"><button class="secondary" data-action="customer-list" ${!can('oa_list_conversations')||busy?'disabled':''}>${c?'‹ 客人列表':'更新客人列表'}</button><button class="secondary" data-action="host-refresh" ${busy?'disabled':''}>重新確認</button></div>${!ready?'<p class="note">請保持電腦和 LINE OA 開啟並登入。</p>':''}${customer.error?`<p class="warning" role="alert">${esc(customer.error)}</p>`:''}${customer.notice?`<p class="connection-note" role="status">${esc(customer.notice)}</p>`:''}${customer.sources?.length?'<p class="connection-note"><a href="https://www.sweetfuntw.com/zh/faq" target="_blank" rel="noopener noreferrer">草稿依據：水芳 FAQ</a></p>':''}${busy?'<p class="connection-note" role="status">正在請主機處理…</p>':''}
 ${!c?`<form id="customer-search" class="customer-search"><input name="guest" aria-label="客人完整名稱" placeholder="輸入客人完整名稱" value="${esc(customer.query)}" maxlength="100" required><button class="primary" ${!can('oa_read_conversation')||busy?'disabled':''}>查看對話</button></form><div class="customer-list">${(customer.list?.conversations||[]).map(v=>`<button data-customer-name="${esc(v.display_name)}" ${busy?'disabled':''}><span class="avatar">☏</span><span><b>${esc(v.display_name)}</b>${v.preview?`<small>${esc(v.preview)}</small>`:''}</span><span>›</span></button>`).join('')}</div>${customer.list?'<p class="connection-note">顯示 LINE 目前畫面上的客人，尚未包含全部聊天紀錄。</p>':'<p class="connection-note">選一位客人，我幫你處理。</p>'}`:
 `<div class="customer-guest"><div><h2>${esc(c.display_name)}</h2><small>${esc(c.observed_at?new Date(c.observed_at).toLocaleString('zh-TW'):'')} · 畫面可見對話</small></div><button class="secondary" data-action="customer-reload" ${busy?'disabled':''}>更新</button></div><div class="customer-chat">${c.messages.length?c.messages.map((m,i)=>`<div class="customer-bubble ${m.direction==='outgoing'?'outgoing':'incoming'}">${m.direction==='unknown'?'<small>方向未確認</small>':''}${esc(m.text)}${m.direction==='incoming'?`<button class="suggest-reply" data-customer-suggest="${i}" ${busy?'disabled':''} title="使用此則訊息與水芳 FAQ 草擬回覆">草擬回覆</button>`:''}</div>`).join(''):'<p class="note">目前畫面沒有可讀取的文字訊息。</p>'}</div><div class="quick-replies">${['oa_set_tag','oa_set_name'].map(a=>`<button data-customer-edit="${a}" ${!can(a)||busy?'disabled':''}>${customerActions[a]}</button>`).join('')}</div><form id="customer-compose" class="customer-compose"><textarea name="reply" aria-label="回覆內容" placeholder="輸入要回覆的內容" maxlength="1000" required ${busy?'disabled':''}>${esc(customer.text)}</textarea><button type="button" class="secondary" data-action="customer-polish" ${busy?'disabled':''}>潤飾文字</button><button class="primary" ${!can('oa_reply')||busy?'disabled':''}>預覽回覆</button></form><p class="connection-note">先核對客人與內容，再確認傳送。</p>`}</section>`;
}
async function customerRead(action,payload={}){if(customer.job)return;customer.error='';customer.notice='';customer.sources=[];customer.draft=null;const job=await hostRequest('customer-read',{action,payload,request_id:crypto.randomUUID()});rememberCustomerJob(job);render();await refreshHost();}
async function pollCustomer(){if(!customer.job)return;let result;try{result=await hostRequest('customer-result',{job_id:customer.job.job_id});}catch(e){if(['job_not_found','not_paired','invalid_job_id'].includes(e.code)){rememberCustomerJob(null);customer.error='工作已失效，請重新讀取對話。';return;}throw e;}if(['queued','leased'].includes(result.status))return;rememberCustomerJob(null);
 if(result.status==='succeeded'&&result.output){if(result.action==='oa_list_conversations'){customer.list=result.output;customer.conversation=null;customer.readJobId=null;}else if(result.action==='oa_read_conversation'){customer.conversation=result.output;customer.readJobId=result.job_id;customer.text='';}else{customer.notice='已完成，主機已核對結果。';customer.text='';customer.readJobId=null;customer.conversation=null;customer.draft=null;}}
 else{customer.error=customerErrors[result.error_code]||({expired:'工作已過期，請重新讀取對話。',partial_success:'操作結果尚未確認，請先查看 LINE，勿重複送出。',needs_reauth:'請在電腦重新登入 LINE OA。',blocked:'對話狀態無法確認，請重新讀取。',owner_required:'請在電腦確認 LINE 畫面後重新讀取。'})[result.status]||(customerActions[result.action]?'未能確認操作結果，請先查看 LINE，勿重複送出。':'這次讀取未完成。請確認電腦上的 LINE 畫面後再試。');}
}
async function customerPrepare(action,payload){if(customer.job)return;const readId=customer.readJobId;const d=await hostRequest('customer-prepare',{action,payload,read_job_id:readId});if(customer.readJobId!==readId)return toast('已切換對話，請重新預覽。');customer.draft=d;modal(`<h2>${esc(customerActions[d.action])}</h2><p>客人：<b>${esc(d.display_name)}</b></p><div class="customer-preview">${esc(d.text)}</div><div class="dialog-actions"><button class="secondary" data-action="close">返回修改</button><button class="primary" data-action="customer-confirm">${d.action==='oa_reply'?'確認傳送':'確認修改'}</button></div>`);}
function customerEdit(action){customer.edit='';modal(`<h2>${esc(customerActions[action])}</h2><form id="customer-edit-form" class="form"><label class="field">${action==='oa_set_tag'?'標籤名稱':'新名稱'}<input name="value" maxlength="${20}" required autocomplete="off"></label><button class="primary">預覽修改</button></form>`);$('#customer-edit-form').onsubmit=async e=>{e.preventDefault();try{await customerPrepare(action,{[action==='oa_set_tag'?'tag':'new_name']:new FormData(e.target).get('value')});}catch(e){toast(e.message);}};}
function bindCustomer(){const f=$('#customer-search');if(f)f.onsubmit=async e=>{e.preventDefault();try{await customerRead('oa_read_conversation',{display_name:customer.query.trim()});}catch(e){toast(e.message);}};const c=$('#customer-compose');if(c)c.onsubmit=async e=>{e.preventDefault();try{await customerPrepare('oa_reply',{text:customer.text});}catch(e){toast(e.message);}};}
document.addEventListener('input',e=>{if(e.target.closest('#customer-search'))customer.query=e.target.value;if(e.target.closest('#customer-compose'))customer.text=e.target.value;});

function moreDialog(){modal(`<h2>${esc(bot().name)}</h2><div class="quick-menu"><button data-action="new">新對話</button><button data-action="recent">聊天紀錄</button><button data-tab="tools">工具</button><button data-tab="documents">文件</button><button data-tab="onboarding">資料與連線</button><button data-action="settings">團隊設定</button></div>`);}
function sourceDialog(){modal(`<h2>使用哪份資料？</h2><div class="form"><label class="field">旅宿<select id="property"><option value="sweetfun" ${property==='sweetfun'?'selected':''}>水芳</option><option value="offland" ${property==='offland'?'selected':''}>OFFLAND</option></select></label><label class="field">資料<select id="dataset"><option value="live" ${dataset==='live'?'selected':''}>目前訂單 · 唯讀</option><option value="imported" ${dataset==='imported'?'selected':''}>匯入資料 · 唯讀</option><option value="sandbox" ${dataset==='sandbox'?'selected':''}>測試資料</option></select></label><button class="primary" data-action="close">完成</button></div>`);}
function composer(){return `<div class="composer-wrap"><form id="chat-form" class="composer"><button type="button" class="attach-button" data-tab="onboarding" aria-label="匯入資料">＋</button><textarea id="message" aria-label="輸入訊息" placeholder="輸入訊息" ${pending?'disabled':''} rows="1"></textarea><button class="send" aria-label="傳送" ${pending?'disabled':''}>↑</button></form></div>`;}
function chatHTML(){if(!conversation&&!pending){const intro={concierge:dataset==='sandbox'?'嗨，想先試做什麼？':dataset==='imported'?'想怎麼整理這份訂單？':state.history.available&&property==='sweetfun'?'嗨，水芳訂單已連上。想先看什麼？':'嗨，先傳一份訂單給我吧。',finance:'想核對哪一筆收支？',reservations:'想查訂單，還是看看房況？',analyst:'想看哪個月份的訂房表現？',market:'想研究哪個地區或競品？'};return `<div class="messages chat-start"><article class="message assistant"><div class="assistant-text">${esc(intro[bot().role]||'有什麼需要我幫忙？')}</div></article><div class="quick-replies">${role().prompts.slice(0,2).map((p,i)=>`<button data-prompt="${esc(p)}">${({concierge:['營運概況','本月分析'],finance:['本月房費','查付款'],reservations:['本月訂單','查房況'],analyst:['本月分析','房間與通路'],market:['市場報告','競品資料']}[bot().role]||['開始','查詢'])[i]}</button>`).join('')}${bot().role==='concierge'?'<button data-tab="onboarding">匯入訂單</button>':''}</div></div>`;}
 return `<div class="messages">${(conversation?.messages||[]).map(m=>`<article class="message ${m.role}">${m.role==='user'?`<div class="user-text">${esc(m.text)}</div>`:`<div class="message-head">${avatar(bot())}<span>${esc(bot().name)}</span><span class="muted">${new Date(m.at).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="assistant-text">${esc(m.text)}</div>${m.error?`<div class="warning">${esc(m.error.message||m.error.code||'處理未完成')}</div>`:''}${(m.cards||[]).map(cardHTML).join('')}${m.trace?.length?`<details class="trace"><summary>查看 ${m.trace.length} 項工具紀錄</summary>${m.trace.map(t=>`<p>${t.status==='completed'?'✓':'!'} ${esc(toolNames[t.tool]||t.tool)}</p>`).join('')}</details>`:''}`}</article>`).join('')}${pending?`<div class="pending"><span class="spinner"></span>${esc(bot().name)}正在確認資料與工具權限…</div>`:''}</div>`;}
function tableHTML(rows){if(!rows?.length)return '<p class="note">目前沒有符合範圍的資料。</p>';const columns=[...new Set(rows.flatMap(x=>Object.keys(x)))].filter(x=>!['archived','dataset','property'].includes(x));return `<div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th>${esc(names[c]||c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td title="${esc(fmt(row[c]))}" class="${typeof row[c]==='number'?'number':''}">${esc(fmt(row[c]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function cardHTML(c){let body='';if(c.kind==='report'){body=`<div class="report-meta">${esc(c.range.start)} — ${esc(c.range.end)}（不含結束日） · 框架 v${c.templateVersion}<br>${esc(c.source.title)} · ${esc(c.source.asof)}</div>${c.sections.map(sec=>`<h4>${esc(sec.title)}</h4>${sec.rows.length===1&&sec.rows[0].label==='全館'?`<div class="metric-grid">${sec.columns.map(col=>`<div class="metric"><small>${esc(col.label)}</small><strong>${esc(fmt(sec.rows[0].values[col.id]))}<em>${esc(col.unit)}</em></strong>${col.id==='occupancy'&&sec.rows[0].values[col.id]!==null?`<div class="bar"><i style="width:${Math.min(100,sec.rows[0].values[col.id])}%"></i></div>`:''}</div>`).join('')}</div>`:`<div class="table-scroll"><table><thead><tr><th>分組</th>${sec.columns.map(col=>`<th>${esc(col.label)}</th>`).join('')}</tr></thead><tbody>${sec.rows.map(row=>`<tr><td>${esc(row.label)}</td>${sec.columns.map(col=>`<td class="number">${esc(fmt(row.values[col.id]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}<details class="note"><summary>指標定義</summary>${sec.columns.map(col=>`<p>${esc(col.label)}：${esc(col.definition)}</p>`).join('')}</details>`).join('')}<p class="note">${esc(c.note)}</p>${[c.source.warning,...c.warnings].filter(Boolean).map(x=>`<p class="note">· ${esc(x)}</p>`).join('')}`;}
 else if(c.kind==='calculation')body=`<div class="report-meta">${esc(c.expression)}</div><div class="big-result">${esc(fmt(c.result))}</div>`;
 else if(c.kind==='table'||c.kind==='documents')body=tableHTML(c.rows)+(c.groups?tableHTML(Object.entries(c.groups).map(([group,count])=>({group,count}))):'');
 else if(c.kind==='finance')body=`<div class="metric-grid">${[['已知訂單總額',c.orderTotal],['該批訂單已收',c.cohortReceipts],['期間淨收款',c.cashFlow],['總額未知訂單',c.unknownOrders]].map(([l,v])=>`<div class="metric"><small>${l}</small><strong>${fmt(v)}</strong></div>`).join('')}</div><h4>收款與沖銷歷史</h4>${tableHTML(c.payments)}`;
 else if(c.kind==='overview')body=`<div class="metric-grid"><div class="metric"><small>有效訂單</small><strong>${c.activeOrders}</strong></div><div class="metric"><small>未完成任務</small><strong>${c.openTasks.length}</strong></div></div>${tableHTML(c.openTasks)}`;
 else if(c.kind==='document')body=`<b>${esc(c.record.title)}</b><p class="doc-content">${esc(c.record.content)}</p>`;
 else if(c.kind==='record')body=tableHTML([c.record]);
 else if(c.kind==='market-report')body=`<div class="report-meta">框架 v${c.templateVersion} · ${esc(c.source.title)}</div>${c.sections.map(sec=>`<h4>${esc(sec.title)}</h4>${tableHTML(sec.group==='comparisons'?c.comparisons:sec.rows)}`).join('')}`;
 else if(c.kind==='delegation')body=`<div class="report-meta">${esc(c.message)}</div>${c.cards.map(cardHTML).join('')}`;
 return `<section class="result-card"><div class="result-head"><h3>${esc(c.title)}</h3><button class="export" data-export="${esc(encodeURIComponent(JSON.stringify(c)))}">匯出 ↗</button></div><details class="report-expand"><summary>查看結果</summary><div class="result-body">${c.source?.asof&&c.kind!=='report'?`<p class="report-meta">同步時間：${esc(c.source.asof)}${c.range?` · ${esc(c.range.start)} 至 ${esc(c.range.end)}（不含結束日）`:""}</p>`:""}${body}${c.note&&c.kind!=='report'?`<p class="note">${esc(c.note)}</p>`:''}<div class="report-meta">${c.dataset==='imported'?'匯入訂單・唯讀':c.dataset==='live'?'正式資料・唯讀':'隔離測試資料'} · ${c.property==='offland'?'遺忘無際':'水芳'}</div></div></details></section>`;}
function documentsHTML(){const can=bot().write.length&&dataset==='sandbox';return `<section class="section-page"><div class="page-heading"><div><h2>工作文件</h2><p>只顯示 ${esc(bot().name)} 有權讀取的文件</p></div>${can?'<button class="primary" data-action="new-doc">＋ 新增文件</button>':''}</div>${dataset!=='sandbox'?'<div class="empty">目前訂單只提供唯讀查詢與固定分析，不提供文件編輯。</div>':docRows.length?`<div class="doc-list">${docRows.map(d=>`<div class="doc-item"><div><b>${esc(d.title)}</b><small>${state.categories[d.category]} · v${d.version}</small></div><button class="secondary" data-doc="${esc(d.id)}">開啟</button></div>`).join('')}</div>`:'<div class="empty">目前沒有可讀取的文件。</div>'}</section>`;}
const fields={
 'orders.list':['start','end','id'],'availability':['start','end'],'orders.create':['room','start','end','guest','total','channel'],'orders.update':['id','version','room','start','end','guest','total','channel'],'orders.cancel':['id','version'],
 'finance.summary':['start','end'],'payments.record':['orderId','amount','method','receivedAt'],'payments.reverse':['id','reason'],'tasks.create':['title','assignee','due'],'tasks.update':['id','version','status'],
 'reports.booking':['start','end'],'market.add':['name','url','stayDate','nights','guests','price','taxIncluded','cancellation','observedAt'],'market.archive':['id','version'],'calculate':['expression'],'organize':['rows','sortBy','groupBy']};
function defaultRange(){if(dataset==='imported'){const p=state.setup.imports.find(x=>x.id===property)?.period;if(p)return p;}const d=new Date(),m=d.toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'}).slice(0,7),end=new Date(m+'-01');end.setUTCMonth(end.getUTCMonth()+1);return {start:m+'-01',end:end.toISOString().slice(0,10)}}
function fieldHTML(k,value){let opts;if(k==='room')opts=property==='sweetfun'?['101','102','201','202','301','302']:['villa'];if(k==='channel')opts=['direct','booking','agoda','airbnb','other'];if(k==='method')opts=['cash','transfer','card'];if(k==='status')opts=['todo','doing','done'];if(k==='assignee')opts=state.bots.filter(x=>x.active).map(x=>x.id);if(k==='taxIncluded')opts=['true','false'];const labels={expression:'算式',rows:'表格資料（JSON 陣列）',sortBy:'排序欄位（可留空）',groupBy:'分組欄位（可留空）',...names,...(!['orders.create','orders.update','availability'].includes(selectedTool)?{start:'期間開始',end:'期間結束（不含當日）'}:{})};const dateFields=['start','end','due','receivedAt','stayDate'];const numbers=['version','total','amount','nights','guests','price'];let v=value??(dateFields.includes(k)?defaultRange()[k]||new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'}):k==='expression'?'12800 * (1 - 15%)':k==='version'?1:k==='nights'?1:k==='guests'?2:k==='observedAt'?new Date().toISOString():k==='rows'?'[{"房間":"101","金額":3200},{"房間":"102","金額":2400}]':'');return `<label class="field">${esc(labels[k]||k)}${opts?`<select name="${k}">${opts.map(o=>`<option value="${o}" ${v===o?'selected':''}>${esc(state.bots.find(x=>x.id===o)?.name||({direct:'直訂',booking:'Booking',agoda:'Agoda',airbnb:'Airbnb',other:'其他',cash:'現金',transfer:'轉帳',card:'刷卡',todo:'待處理',doing:'處理中',done:'已完成',true:'是',false:'否'}[o]||o))}</option>`).join('')}</select>`:k==='rows'?`<textarea name="${k}">${esc(v)}</textarea>`:`<input name="${k}" type="${dateFields.includes(k)?'date':numbers.includes(k)?'number':'text'}" ${numbers.includes(k)?'step="any"':''} value="${esc(v)}" autocomplete="off">`}</label>`;}
function toolsHTML(){const tools=bot().tools.filter(t=>!t.startsWith('documents.')&&t!=='delegate'&&(dataset==='sandbox'||['overview','orders.list','availability','finance.summary','reports.booking','calculate','organize'].includes(t)));if(!tools.includes(selectedTool))selectedTool=tools[0]||'';return `<section class="section-page"><div class="page-heading"><div><h2>授權工具</h2><p>直接操作與聊天使用同一套權限和驗證</p></div><span class="pill">${tools.length} 項可用</span></div>${tools.length?`<select class="tool-selector" id="tool-select" aria-label="選擇工具">${tools.map(t=>`<option value="${t}" ${selectedTool===t?'selected':''}>${toolNames[t]||t}</option>`).join('')}</select><form class="tool-form form" id="tool-form"><h3>${toolNames[selectedTool]}</h3><div class="form-grid">${(fields[selectedTool]||[]).map(k=>fieldHTML(k)).join('')}</div>${selectedTool==='orders.update'?'<p class="note">先查詢訂單取得版本，填入要修改的完整訂單內容。</p>':''}<button class="primary" type="submit">執行${toolNames[selectedTool]}</button></form><div class="tool-result">${toolResult?cardHTML(toolResult):''}</div>`:'<div class="empty">此角色在目前資料來源沒有可用工具。</div>'}</section>`;}
function settingsHTML(){return `<section class="section-page"><div class="page-heading"><div><h2>打造你的團隊</h2><p>由你定義角色、工作範圍與產出框架</p></div><span class="pill">業主設定</span></div><div class="settings-nav">${[['bots','Bot 角色'],['templates','固定報告框架'],['sources','產品與來源'],['audit','操作紀錄']].map(([k,v])=>`<button class="secondary" data-settings="${k}">${v}</button>`).join('')}</div><div id="settings-body">${settingsTab==='bots'?`${state.bots.map(b=>`<div class="bot-settings"><div class="row"><div class="row">${avatar(b)}<b>${esc(b.name)}</b><span class="pill">${b.active?'啟用':'停用'}</span></div><button class="secondary" data-edit-bot="${esc(b.id)}">編輯</button></div><p>${esc(b.mission)}</p><div class="tag-list"><span class="tag">${state.roles[b.role].name}能力範圍</span><span class="tag">${b.tools.length} 項工具</span></div></div>`).join('')}<button class="primary" data-action="new-bot">＋ 新增自訂 Bot</button>`:settingsTab==='templates'?state.templates.map(t=>`<div class="bot-settings"><div class="row"><b>${esc(t.title)}</b><button class="secondary" data-template="${t.id}">編輯框架</button></div><p>${t.sections.map(s=>esc(s.title)).join(' → ')}</p><p class="note">${esc(t.note)}</p><span class="pill">版本 ${t.version} · 模型不可修改</span></div>`).join(''):settingsTab==='sources'?`<div class="warning">水芳目前訂單唯讀；測試交易保存在獨立隔離區，不會修改正式訂单。</div>${state.setup.connections.map(p=>`<div class="product-row"><div class="row"><b>${esc(p.name)}</b><span class="pill">${esc(p.state)}</span></div><small>${esc(p.detail)} · ${esc(p.owner)}</small>${p.url?`<a class="secondary product-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">開啟產品 ↗</a>`:''}${p.role?`<button class="secondary" data-bot="${p.role}">交給${esc(state.roles[p.role].name)}</button>`:''}</div>`).join('')}<div class="source-card"><b>水芳目前訂單</b><p class="note">${state.history.available?`水芳 · ${state.history.rows} 筆匿名房晚 · 資料截至 ${esc(state.history.asof)}。沿用管理系統的匿名訂單同步來源。`:'快照未接入。'}</p></div>`:'<p class="note">正在讀取操作紀錄…</p>'}</div></section>`;}
function scrollBottom(){requestAnimationFrame(()=>{const el=$('#content');if(el)el.scrollTop=el.scrollHeight;});}
function modal(html){$('#dialog').innerHTML=`<button class="close-dialog" data-action="close" aria-label="關閉">×</button>${html}`;$('#dialog').showModal();}
async function loadDocs(){if(dataset!=='sandbox'){docRows=[];return;}const out=await tool('documents.list',{});docRows=out.rows;}
async function tool(name,args){return post('tool',{botId,property,dataset,tool:name,args,key:crypto.randomUUID()});}
async function send(message){if(pending||!message.trim())return;const prior=conversation;pending=true;conversation=conversation||{messages:[]};conversation.messages.push({role:'user',text:message,at:new Date().toISOString()});render();try{const r=await post('chat',{botId,property,dataset,message,conversationId:prior?.id,requestId:crypto.randomUUID()});if(!r.conversation)throw Error(r.message||'工作中斷，請檢查紀錄。');conversation=r.conversation;await refresh();}catch(e){toast(e.message);conversation=prior;if(conversation)conversation.messages.pop();}finally{pending=false;render();}}
function bindForms(){const chat=$('#chat-form');if(chat){chat.onsubmit=e=>{e.preventDefault();send($('#message').value)};$('#message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send($('#message').value)}};}
 const tf=$('#tool-form');if(tf)tf.onsubmit=async e=>{e.preventDefault();const b=tf.querySelector('button[type=submit]');b.disabled=true;try{const a={};for(const [k,v]of new FormData(tf)){if(v==='')continue;a[k]=['version','total','amount','nights','guests','price'].includes(k)?Number(v):k==='taxIncluded'?v==='true':k==='rows'?JSON.parse(v):v;}toolResult=await tool(selectedTool,a);render();}catch(e){toast(e.message);b.disabled=false;}};
}
function botDialog(id){let b=id?structuredClone(state.bots.find(x=>x.id===id)):{role:'analyst',name:'我的分析助理',mission:state.roles.analyst.mission,read:[...state.roles.analyst.read],write:[...state.roles.analyst.write],tools:[...state.roles.analyst.tools],active:true};
 function draw(){const r=state.roles[b.role];modal(`<h2>${id?'編輯 Bot':'新增自訂 Bot'}</h2><form class="form" id="bot-form"><label class="field">Bot 名稱<input name="name" value="${esc(b.name)}" required maxlength="40"></label><label class="field">能力角色（權限上限）<select name="role" id="bot-role">${Object.entries(state.roles).map(([k,v])=>`<option value="${k}" ${k===b.role?'selected':''}>${v.name}</option>`).join('')}</select></label><label class="field">角色職責<textarea name="mission" required maxlength="1200">${esc(b.mission)}</textarea></label>${[['read','可讀文件'],['write','可新增／修改／封存文件'],['tools','可用工具']].map(([k,title])=>`<div class="field">${title}<div class="checks">${r[k].map(v=>`<label class="check"><input type="checkbox" name="${k}" value="${v}" ${b[k].includes(v)?'checked':''}>${esc(k==='tools'?toolNames[v]||v:state.categories[v])}</label>`).join('')}</div></div>`).join('')}<label class="check"><input type="checkbox" name="active" ${b.active?'checked':''}>啟用 Bot</label><div class="dialog-actions"><button type="button" class="secondary" data-action="close">取消</button><button class="primary">儲存角色</button></div></form>`);
 $('#bot-role').onchange=e=>{b.name=$('#bot-form [name=name]').value;b.role=e.target.value;const r=state.roles[b.role];b.mission=r.mission;for(const k of ['read','write','tools'])b[k]=[...r[k]];$('#dialog').close();draw();};
 $('#bot-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),v={...b,name:f.get('name'),mission:f.get('mission'),active:f.has('active')};for(const k of ['read','write','tools'])v[k]=f.getAll(k);try{await post('bots',v);await refresh();$('#dialog').close();if(!state.bots.find(x=>x.id===botId)?.active)botId=state.bots.find(x=>x.active)?.id||'concierge';render();toast('角色與權限已儲存。')}catch(e){toast(e.message)}};}
 draw();}
async function docDialog(id){const d=id?(await tool('documents.read',{id})).record:null,can=!d||bot().write.includes(d.category);modal(`<h2>${d?'工作文件':'新增文件'}</h2>${can?`<form id="doc-form" class="form"><label class="field">分類<select name="category" ${d?'disabled':''}>${bot().write.map(k=>`<option value="${k}" ${d?.category===k?'selected':''}>${state.categories[k]}</option>`).join('')}</select></label><label class="field">標題<input name="title" value="${esc(d?.title||'')}" maxlength="150" required></label><label class="field">內容<textarea name="content" style="min-height:220px" maxlength="20000" required>${esc(d?.content||'')}</textarea></label><div class="dialog-actions">${d?`<button type="button" class="secondary danger" id="archive-doc">封存文件</button>`:''}<button class="primary">儲存文件</button></div></form>`:`<h3>${esc(d.title)}</h3><div class="doc-content">${esc(d.content)}</div><p class="note">此文件僅有讀取權限。</p>`}`);
 if(can){$('#doc-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await tool(d?'documents.update':'documents.create',{id:d?.id,version:d?.version,category:d?.category||f.get('category'),title:f.get('title'),content:f.get('content')});await loadDocs();$('#dialog').close();render();toast('文件已儲存。')}catch(e){toast(e.message)}};if(d)$('#archive-doc').onclick=async()=>{try{await tool('documents.archive',{id:d.id,version:d.version});await loadDocs();$('#dialog').close();render();toast('文件已封存，操作紀錄保留。')}catch(e){toast(e.message)}};}}
function templateDialog(id){let t=structuredClone(state.templates.find(x=>x.id===id));function read(){t.title=$('#template-form [name=title]').value;t.note=$('#template-form [name=note]').value;t.sections=[...document.querySelectorAll('.template-section')].map(el=>({title:el.querySelector('[name=section-title]').value,group:el.querySelector('[name=group]').value,metrics:[...el.querySelectorAll('[name=metric]:checked')].map(x=>x.value)}));}
 function draw(){modal(`<h2>編輯固定報告框架</h2><form class="form" id="template-form"><label class="field">報告名稱<input name="title" value="${esc(t.title)}" maxlength="100" required></label><p class="note">以下順序就是報告順序。Bot 只能填入選定的指標。</p><div>${t.sections.map((sec,i)=>`<div class="template-section"><div class="row"><b>章節 ${i+1}</b><button type="button" class="secondary" data-remove-section="${i}">移除</button></div><label class="field">章節標題<input name="section-title" value="${esc(sec.title)}" required maxlength="80"></label><label class="field">分組<select name="group">${(id==='booking'?[['all','全館'],['room','依房間'],['channel','依通路']]:[['evidence','證據列表'],['comparisons','可比價格摘要'],['gaps','資料缺口']]).map(([k,v])=>`<option value="${k}" ${sec.group===k?'selected':''}>${v}</option>`).join('')}</select></label>${id==='booking'?`<div class="checks">${Object.entries(state.metrics).map(([k,v])=>`<label class="check"><input type="checkbox" name="metric" value="${k}" ${sec.metrics.includes(k)?'checked':''}>${v.label}</label>`).join('')}</div>`:''}</div>`).join('')}</div><button type="button" class="secondary" id="add-section">＋ 新增章節</button><label class="field">固定說明<textarea name="note" required maxlength="1000">${esc(t.note)}</textarea></label><div class="dialog-actions"><button class="primary">儲存框架版本</button></div></form>`);
 $('#add-section').onclick=()=>{read();if(t.sections.length>=8)return toast('最多 8 個章節。');t.sections.push({title:'新的章節',group:id==='booking'?'all':'gaps',metrics:id==='booking'?['occupied']:[]});$('#dialog').close();draw();};
 document.querySelectorAll('[data-remove-section]').forEach(el=>el.onclick=()=>{read();t.sections.splice(Number(el.dataset.removeSection),1);$('#dialog').close();draw();});
 $('#template-form').onsubmit=async e=>{e.preventDefault();read();try{await post('templates',t);await refresh();$('#dialog').close();render();toast('新框架已儲存；後續報告將使用此版本。')}catch(e){toast(e.message)}};
 }draw();}
function download(c){const lines=[`# ${c.title}`,'',`資料來源：${c.dataset==='imported'?'匯入訂單・唯讀':c.dataset==='live'?'唯讀目前訂單':'隔離測試資料'}`,`據點：${c.property}`,''];if(c.kind==='report'){lines.push(`框架版本：${c.templateVersion}`,`期間：${c.range.start} 至 ${c.range.end}（不含結束日）`,`來源：${c.source.title}，${c.source.asof}`,'');for(const sec of c.sections){lines.push(`## ${sec.title}`,'',`| 分組 | ${sec.columns.map(x=>x.label).join(' | ')} |`,`| --- | ${sec.columns.map(()=>'---').join(' | ')} |`,...sec.rows.map(r=>`| ${r.label} | ${sec.columns.map(x=>fmt(r.values[x.id])).join(' | ')} |`),'');}lines.push(c.note,...c.warnings);}else lines.push('```json',JSON.stringify(c,null,2),'```');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=c.title+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function goTab(next){tab=next;toolResult=null;if(tab==='documents'){try{await loadDocs()}catch(e){docRows=[];toast(e.message)}}render();if(tab==='settings'&&settingsTab==='audit')loadAudit();}
async function loadAudit(){try{const r=await api('audit');if($('#settings-body'))$('#settings-body').innerHTML=tableHTML(r.rows.map(x=>({時間:x.at,角色:x.botId||'業主',工具:toolNames[x.tool]||x.tool,狀態:x.status,紀錄:x.recordId||'—'})));}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;try{if($('#dialog').open&&el.closest('.quick-menu'))$('#dialog').close();
 if(el.dataset.customerSuggest!==undefined){el.disabled=true;el.textContent='正在草擬…';try{const readId=customer.readJobId,original=customer.text;const d=await hostRequest('customer-suggest',{read_job_id:readId,message_index:Number(el.dataset.customerSuggest)});if(customer.readJobId!==readId||customer.text!==original)return toast('對話或草稿已變更，請重新草擬。');customer.text=d.reply;customer.sources=d.sources;customer.notice=d.needs_owner?'這則問題需要你確認，草稿已準備好。':'已依水芳 FAQ 草擬，請核對後再傳送。';render();}finally{el.disabled=false;el.textContent='草擬回覆';}}
 if(el.dataset.customerName){customer.query=el.dataset.customerName;await customerRead('oa_read_conversation',{display_name:el.dataset.customerName});}
 if(el.dataset.customerEdit)customerEdit(el.dataset.customerEdit);
 if(el.dataset.bot){if(pending)return toast('目前工作完成後可切換角色。');botId=el.dataset.bot;conversation=null;toolResult=null;await goTab('chat');}
 if(el.dataset.history){if(pending)return;conversation=await api('conversation?id='+encodeURIComponent(el.dataset.history));botId=conversation.botId;property=conversation.property;dataset=conversation.dataset;tab='chat';render();}
 if(el.dataset.tab)await goTab(el.dataset.tab);
 if(el.dataset.settings){settingsTab=el.dataset.settings;render();if(settingsTab==='audit')loadAudit();}
 if(el.dataset.prompt)send(el.dataset.prompt);
 if(el.dataset.editBot)botDialog(el.dataset.editBot);
 if(el.dataset.doc)await docDialog(el.dataset.doc);
 if(el.dataset.template)templateDialog(el.dataset.template);
 if(el.dataset.export)download(JSON.parse(decodeURIComponent(el.dataset.export)));
 switch(el.dataset.action){case'customer-polish':{if(!customer.text.trim())return toast('先輸入想回覆的內容。');el.disabled=true;el.textContent='正在潤飾…';const original=customer.text,readId=customer.readJobId;try{const result=await hostRequest('customer-polish',{text:original});if(customer.text===original&&customer.readJobId===readId){customer.text=result.reply;render();}else toast('文字已修改，請重新潤飾。');}finally{el.disabled=false;el.textContent='潤飾文字';}break;}case'customer-list':await customerRead('oa_list_conversations');break;case'customer-reload':await customerRead('oa_read_conversation',{display_name:customer.conversation.display_name});break;case'customer-confirm':{if(!customer.draft||customer.job)break;el.disabled=true;try{rememberCustomerJob(await hostRequest('customer-confirm',{draft_id:customer.draft.draft_id,confirmed:true}));$('#dialog').close();render();await refreshHost();}catch(e){el.disabled=false;throw e;}break;}case'customer':if(pending)return toast('訊息處理中');tab='customer';conversation=null;render();await refreshHost();break;case'host-pair':await pairHost();break;case'host-refresh':await refreshHost();break;case'host-probe':await hostRequest('probe',{request_id:crypto.randomUUID()});await refreshHost();break;case'host-disconnect':await hostRequest('disconnect',{});hostPairing=null;await refreshHost();break;case'more':if(tab==='customer'){modal(`<h2>民宿客服</h2><p>${esc(hostLabel())}</p>${hostState?.paired?'<button class="secondary" data-action="host-disconnect">中斷主機連線</button>':''}`);break;}moreDialog();break;case'source-picker':sourceDialog();break;case'recent':modal('<h2>聊天紀錄</h2><div class="quick-menu">'+histories.filter(x=>x.botId===botId).map(x=>`<button data-history="${esc(x.id)}">${esc(x.title)}</button>`).join('')+'</div>');break;case'menu':$('.shell').classList.toggle('menu-open');break;case'close':$('#dialog').close();break;case'new':if(!pending){conversation=null;tab='chat';render();}break;case'settings':settingsTab='bots';await goTab('settings');break;case'sources':settingsTab='sources';await goTab('settings');break;case'audit':settingsTab='audit';await goTab('settings');break;case'new-bot':botDialog();break;case'new-doc':await docDialog();break;}
 }catch(e){toast(e.message)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='property'||e.target.id==='dataset'){if(pending){render();return toast('目前工作完成後可切換資料。');}if(e.target.id==='property')property=e.target.value;else dataset=e.target.value;if(property==='offland'&&dataset==='live'){dataset='sandbox';toast('OFFLAND 尚無目前訂單，使用隔離測試資料。');}conversation=null;if($('#dialog').open)$('#dialog').close();await goTab(tab);}if(e.target.id==='tool-select'){selectedTool=e.target.value;toolResult=null;render();}}catch(e){toast(e.message)}});
let importFile=null,importInspection=null,importPreview=null,importOptions=null;
const importLabels={room:'房間／房號（必填）',start:'入住日期（必填）',end:'退房日期（必填）',amount:'房費',channel:'通路',status:'訂單狀態',id:'訂單編號',book:'預訂日期'};
function advancedOnboardingHTML(){const r=bot().role,p=state.setup.profiles.find(x=>x.id===property+':'+r),saved=state.setup.imports.find(x=>x.id===property),live=property==='sweetfun'&&state.history.available;return `<section class="section-page onboarding"><div class="eyebrow">${r==='concierge'?'WELCOME HOME':'YOUR SPECIALIST'}</div><h2>${r==='concierge'?'我是總管家，先把資料準備好。':`${esc(bot().name)} · 工作設定`}</h2><p class="note">先準備訂房資料，開始查房與分析。財務、市場研究在你需要時再設定；設定不會改變正式訂單。</p><div class="setup-steps"><span>1 連結訂房資料</span><span>2 核對資料口徑</span><span>3 交給專業角色</span></div><form id="setup-form" class="form source-card"><h3>${r==='finance'?'財務經理先確認你的工作目標':r==='market'?'市場調查經理先確認研究範圍':'使用哪一份訂房資料？'}</h3><label class="field">資料來源<select name="source"><option value="existing" ${p?.source==='existing'?'selected':''} ${!live?'disabled':''}>既有水芳訂單${live?'（已找到同步資料）':'（暫時無法讀取）'}</option><option value="imported" ${p?.source==='imported'?'selected':''} ${!saved?'disabled':''}>已匯入檔案${saved?' · '+esc(saved.sourceName):'（先完成下方匯入）'}</option><option value="later" ${p?.source==='later'||!live&&!saved?'selected':''}>先試用隔離資料，稍後設定</option></select></label>${live?`<p class="note">已找到 ${state.history.rows} 筆匿名房晚。同步時間：${esc(state.history.asof)}，不需要重複上傳。</p>`:''}<label class="field">${r==='market'?'研究目標':r==='finance'?'核對目標':'這次想先完成什麼？'}<textarea name="goal" maxlength="500" placeholder="${r==='market'?'例如：下個月週末、雙人房、含稅可取消報價':r==='finance'?'例如：核對本月表載房費與缺少金額的訂單':'例如：查看本月訂房與通路表現'}">${esc(p?.goal||'')}</textarea></label>${r==='market'?`<label class="field">競品名稱與網址（每行一個）<textarea name="competitors" maxlength="1000">${esc(p?.competitors||'')}</textarea></label><div class="warning">Grok 掃描尚未接通。這裡會保存研究需求；目前市場證據工具使用隔離資料，不能代表真實市場行情。</div>`:r==='finance'?'<div class="warning">已有訂單可做表載房費核對。尚未接入銀行、平台結算、成本與費用，實收、未收與淨利保持未知。</div>':''}<button class="primary">${p?'更新設定並開始工作':'儲存設定並開始工作'}</button></form><details ${!live&&!saved?'open':''} class="import-section"><summary>匯入其他訂單資料 · Excel / CSV / Google Sheet</summary><p class="note">Excel、CSV、TSV、JSON，最多 2 MB。私有 Google Sheet 請先下載 Excel。</p><form id="import-file-form" class="form"><label class="field">選擇檔案<input id="import-file" type="file" accept=".xlsx,.csv,.tsv,.txt,.json"></label><label class="field">或貼上可讀取的 Google Sheet 網址<input name="url" type="url" placeholder="https://docs.google.com/spreadsheets/d/…"></label><button class="secondary">讀取並核對欄位</button></form><div id="import-mapping"></div></details>${saved?`<div class="source-card"><b>目前匯入資料</b><p>${esc(saved.sourceName)} · ${saved.rowCount} 房晚 · ${esc(saved.importedAt)}</p><p class="note">期間 ${esc(saved.period.start)} 至 ${esc(saved.period.end)}（不含結束日）。重新匯入會取代此據點的匯入快照，正式來源不受影響。</p></div>`:''}<h3>你的產品與團隊</h3>${state.setup.connections.map(c=>`<div class="product-row"><div class="row"><b>${esc(c.name)}</b><span class="pill">${esc(c.state)}</span></div><p class="note">${esc(c.detail)}</p>${c.url?`<a class="secondary product-link" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">開啟${esc(c.name)} ↗</a>`:''}</div>`).join('')}</section>`;}
function onboardingHTML(){const p=state.setup.profiles.find(x=>x.id===property+':'+bot().role),saved=state.setup.imports.find(x=>x.id===property),live=property==='sweetfun'&&state.history.available;const advanced=advancedOnboardingHTML(),start=advanced.indexOf('<details '),end=advanced.indexOf('<h3>你的產品與團隊');return `<section class="section-page onboarding compact-setup"><h2>資料與連線</h2><form id="setup-form" class="form"><label class="field">使用資料<select name="source"><option value="existing" ${!live?'disabled':''} ${p?.source==='existing'?'selected':''}>水芳目前訂單${live?' · 已連線':' · 未連線'}</option><option value="imported" ${!saved?'disabled':''} ${p?.source==='imported'?'selected':''}>匯入檔案${saved?' · '+esc(saved.sourceName):''}</option><option value="later" ${p?.source==='later'||!live&&!saved?'selected':''}>測試資料</option></select></label>${['finance','market'].includes(bot().role)?`<label class="field">想先處理什麼？<input name="goal" maxlength="500" value="${esc(p?.goal||'')}" placeholder="告訴我你的目標"></label>`:''}${bot().role==='market'?`<label class="field">競品名稱或網址<textarea name="competitors" maxlength="1000">${esc(p?.competitors||'')}</textarea></label>`:''}<button class="primary">開始聊天</button></form>${advanced.slice(start,end)}<details class="product-connections"><summary>其他產品</summary>${state.setup.connections.map(c=>`<div class="product-row"><b>${esc(c.name)}</b><small>${esc(c.state)}</small>${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">開啟 ↗</a>`:''}</div>`).join('')}</details></section>`;}
function bindOnboarding(){const setup=$('#setup-form');if(setup)setup.onsubmit=async e=>{e.preventDefault();const button=setup.querySelector('button');button.disabled=true;try{const f=Object.fromEntries(new FormData(setup));await post('onboarding',{...f,property,role:bot().role});dataset=f.source==='existing'?'live':f.source==='imported'?'imported':'sandbox';await refresh();conversation=null;await goTab('chat');toast('設定已保存，可以開始工作。')}catch(e){toast(e.message);button.disabled=false;}};
 const form=$('#import-file-form');if(form)form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;b.textContent='正在讀取…';try{const f=$('#import-file').files[0],url=new FormData(form).get('url');if(f){if(f.size>2*1024*1024)throw Error('最多 2 MB，請縮小檔案。');importFile={name:f.name,base64:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f);})};}else if(url)importFile={url};else throw Error('請選擇檔案或貼上 Google Sheet 網址。');importInspection=await post('import',{...importFile,property,stage:'inspect'});if(importInspection.sheetFile)importFile=importInspection.sheetFile;importPreview=null;drawImportMapping(0);}catch(e){toast(e.message);}finally{b.disabled=false;b.textContent='讀取並核對欄位';}};
}
function drawImportMapping(index,header){const sheet=importInspection.sheets[index];header=header??sheet.headerRow;const headers=sheet.headers[header]||[];$('#import-mapping').innerHTML=`<form id="mapping-form" class="form"><h3>核對欄位與計算方式</h3><div class="form-grid"><label class="field">工作表<select id="import-sheet">${importInspection.sheets.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">標題列<select id="import-header">${sheet.headers.map((x,i)=>`<option value="${i}" ${i===header?'selected':''}>第 ${i+1} 列 · ${esc(x.slice(0,3).join(' / '))}</option>`).join('')}</select></label>${Object.entries(importLabels).map(([k,label])=>`<label class="field">${label}<select name="${k}"><option value="-1">未提供</option>${headers.map((h,i)=>`<option value="${i}" ${header===sheet.headerRow&&sheet.mapping[k]===i?'selected':''}>${esc(h||'第 '+(i+1)+' 欄')}</option>`).join('')}</select></label>`).join('')}<label class="field">金額口徑<select name="amountBasis" required><option value="">請確認</option><option value="total">整筆住宿總額（依晚數均分）</option><option value="nightly">每晚房費</option><option value="unknown">金額未知，不列入房費計算</option></select></label><label class="field">日期格式<select name="dateOrder"><option value="ymd">年／月／日（或 Excel 日期）</option><option value="dmy">日／月／年</option><option value="mdy">月／日／年</option></select></label></div><label class="field">完整房間清單（逗號分隔，也要包含空房）<input name="rooms" value="${property==='sweetfun'?'101,102,201,202,301,302':'villa'}" required></label><p class="note">${sheet.rowCount} 列。日期不明、房間不符會列為待修正；同房同晚衝突只計一晚、金額不計。未提供狀態的列視為有效訂單。</p><button class="primary">預覽匯入結果</button></form><div id="import-preview"></div>`;
 $('#import-sheet').onchange=e=>drawImportMapping(Number(e.target.value));$('#import-header').onchange=e=>drawImportMapping(index,Number(e.target.value));
 $('#mapping-form').onchange=()=>{$('#import-preview').innerHTML='';importPreview=null;};
 $('#mapping-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));importOptions={sheetIndex:index,headerRow:header,mapping:Object.fromEntries(Object.keys(importLabels).map(k=>[k,Number(f[k])])),rooms:f.rooms,amountBasis:f.amountBasis,dateOrder:f.dateOrder};importPreview=await post('import',{...importFile,property,stage:'preview',options:importOptions});const v=importPreview;$('#import-preview').innerHTML=`<h3>預覽 · ${v.rowCount} 房晚</h3><p class="note">${esc(v.period.start)} 至 ${esc(v.period.end)}（不含結束日） · 略過取消 ${v.canceled} 筆、重複 ${v.duplicates} 筆、無效 ${v.issueCount} 筆；衝突 ${v.conflicts} 房晚。</p>${tableHTML(v.rows.map(r=>({房間:r.room,日期:r.day,通路:r.channel,表載房費:r.fee,核對:r.ambiguous?'衝突待確認':'可讀取'})))}${v.issueCount?tableHTML(v.issues):''}<label class="check"><input type="checkbox" id="confirm-import">我已核對以上結果${v.issueCount?'，同意略過無效資料列':''}；保存會取代此據點先前匯入的快照。</label><button class="primary" id="commit-import" disabled>確認保存唯讀資料</button>`;$('#confirm-import').onchange=e=>{$('#commit-import').disabled=!e.target.checked;};$('#commit-import').onclick=async()=>{const button=$('#commit-import');button.disabled=true;try{await post('import',{...importFile,property,stage:'commit',options:importOptions,confirmHash:v.hash,acceptSkipped:$('#confirm-import').checked,expectedPreviousHash:state.setup.imports.find(x=>x.id===property)?.hash||null});await post('onboarding',{property,role:'concierge',source:'imported',goal:'使用匯入訂單分析'});dataset='imported';conversation=null;await refresh();importFile=importInspection=importPreview=null;render();toast('已保存，可切換分析專家產出報告。')}catch(e){toast(e.message);button.disabled=false;}};}catch(e){toast(e.message);}finally{b.disabled=false;}};
}
try{csrf=(await api('bootstrap')).csrf;await refresh();render();if(tab==='customer')await refreshHost();}catch(e){$('#app').innerHTML=`<div class="boot">無法開啟工作台：${esc(e.message)}，請重新整理。</div>`;}
